pub enum DataColumnSidecarOrigin {
    Api(Option<OneshotSender<Result<ValidationOutcome>>>),
    BackSync,
    ExecutionLayer,
    Gossip(SubnetId, GossipId),
    Requested(PeerId),
    Own,
}

