    pub fn split(
        self,
    ) -> (
        Option<GossipId>,
        Option<OneshotSender<Result<ValidationOutcome>>>,
    ) {
        match self {
            Self::Gossip(_, gossip_id) => (Some(gossip_id), None),
            Self::Api(sender) => (None, sender),
            Self::BackSync | Self::ExecutionLayer | Self::Own | Self::Requested(_) => (None, None),
        }
    }

